require_once __DIR__.'/includes/email.php';Auth::requireLogin();$attachment=Database::fetch('SELECT a.*,m.account_id message_account_id FROM email_attachments a LEFT JOIN email_messages m ON m.id=a.message_id WHERE a.id=?',[(int)($_GET['id']??0)]);if(!$attachment||!$attachment['message_id']){http_response_code(404);exit('فایل در دسترس نیست.');}try{$message=email_message((int)$attachment['message_id']);}catch(Throwable){http_response_code(404);exit('فایل در دسترس نیست.');}$root=realpath(dirname(__DIR__));$allowed=$root?realpath($root.'/uploads/email'):false;$full=$root?realpath($root.str_replace('/',DIRECTORY_SEPARATOR,$attachment['storage_path'])):false;if(!$full||!$allowed||!str_starts_with(strtolower($full),strtolower($allowed.DIRECTORY_SEPARATOR))||!is_file($full)){http_response_code(404);exit('فایل در دسترس نیست.');}$mime=preg_replace('/[^a-z0-9.+-\/]/i','',(string)$attachment['mime_type'])?:'application/octet-stream';$name=preg_replace('/[\r\n"\\]/u','_',basename((string)$attachment['file_name']));header('Content-Type: '.$mime);header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: sandbox');header('Cache-Control: private, no-store');header('Content-Disposition: attachment; filename="'.rawurlencode($name).'"');header('Content-Length: '.filesize($full));EmailHubModule::log((int)$message['account_id'],(int)$message['id'],'attachment_downloaded','پیوست ایمیل دانلود شد.');readfile($full);exit;
